import { describe, expect, it } from 'vitest';
import { getCodeRanges } from './getCodeRanges.js';
const slices = (content) => getCodeRanges(content).map(([start, end]) => content.slice(start, end));
describe('getCodeRanges', () => {
    it('returns nothing for an empty page', () => {
        expect(getCodeRanges('')).toEqual([]);
    });
    it('covers a fence including its fence lines', () => {
        const content = 'Intro\n\n```js\nconst a = <br>;\n```\n\nOutro';
        expect(getCodeRanges(content)).toEqual([[7, 32]]);
        expect(slices(content)).toEqual(['```js\nconst a = <br>;\n```']);
    });
    it('covers a fence inside a blockquote', () => {
        expect(slices('> Quote\n>\n> ```js\n> x\n> ```\n\nAfter')).toEqual(['```js\n> x\n> ```']);
    });
    it('does not close a fence on a line with an info string', () => {
        expect(slices('```\na\n```js\nb\n```\nc')).toEqual(['```\na\n```js\nb\n```']);
    });
    it('runs an unclosed fence to the end of the file', () => {
        expect(slices('Text\n\n```bash\necho hi\n\n<br>\n')).toEqual(['```bash\necho hi\n\n<br>\n']);
    });
    it('pairs inline code within a block but not across blank lines', () => {
        expect(slices('Use `a` and ``b ` c``.')).toEqual(['`a`', '``b ` c``']);
        expect(slices('Open `tick\n\nclose` here')).toEqual([]);
    });
    it('covers YAML frontmatter', () => {
        expect(slices('---\ntitle: `x`\n---\n\nBody `y`')).toEqual(['---\ntitle: `x`\n---', '`y`']);
    });
    it('covers TOML frontmatter', () => {
        expect(slices('+++\ntitle = "x"\n+++\n\nBody')).toEqual(['+++\ntitle = "x"\n+++']);
    });
    it('keeps offsets exact after a byte order mark', () => {
        expect(slices('﻿---\na: 1\n---\n\n`b`')).toEqual(['---\na: 1\n---', '`b`']);
    });
    it('does not treat indented lines inside JSX as code', () => {
        expect(slices('<Card>\n    <br>\n    Text `x`\n</Card>')).toEqual(['`x`']);
    });
    it('finds fences indented inside JSX', () => {
        expect(slices('<Tab>\n    ```js\n    x\n    ```\n</Tab>')).toEqual(['```js\n    x\n    ```']);
    });
    it('finds code on pages with broken JSX', () => {
        const content = '<Card title="a">\n\nLine<br>\n\n```html\n<br>\n```\n\nSee `<br>`.\n';
        expect(slices(content)).toEqual(['```html\n<br>\n```', '`<br>`']);
    });
    it('matches the mdast positions on a mixed page', () => {
        const content = [
            '---',
            'title: `Page`',
            '---',
            '',
            'Intro with `inline` and ``double ` tick`` code.',
            '',
            '<Card title="a">',
            '',
            'Line<br>',
            '',
            '```js title="x.js"',
            'const a = <br>;',
            '```',
            '',
            '> Quote',
            '> ```bash',
            '> echo `x`',
            '> ```',
            '',
            '- Item `one`',
            '',
            '    ```py',
            '    print(1)',
            '    ```',
            '',
            '<Tab>',
            '    indented `two`',
            '</Tab>',
            '',
            'Open `tick',
            '',
            'close` here',
            '',
            '~~~',
            'tilde',
            '~~~',
            '',
            '```',
            'unclosed',
            '',
        ].join('\n');
        expect(getCodeRanges(content)).toEqual([
            [0, 21],
            [34, 42],
            [47, 64],
            [100, 138],
            [150, 174],
            [183, 188],
            [194, 220],
            [241, 246],
            [280, 293],
            [295, 308],
        ]);
        expect(getCodeRanges('+++\na = 1\n+++\n\n`b`')).toEqual([
            [0, 13],
            [15, 18],
        ]);
    });
    it('does not pair backticks across table cells', () => {
        expect(slices('| A | B |\n| - | - |\n| `open | <br> close` |')).toEqual([]);
    });
    it('covers inline code inside table cells', () => {
        const content = '| A | B |\n| - | - |\n| `x` | y `<br>` |';
        expect(getCodeRanges(content)).toEqual([
            [22, 25],
            [30, 36],
        ]);
        expect(slices(`﻿${content}`)).toEqual(['`x`', '`<br>`']);
    });
    it('ignores HTML and autolink syntax like MDX does', () => {
        expect(slices('<div>\n\n`a`\n\n</div>\n\n<https://x.com/`b`>')).toEqual(['`a`', '`b`']);
    });
});
